argv:
json=$(mktemp); err=$(mktemp); trap 'rm -f "$json" "$err"' EXIT; cargo test --locked -p inir-companiond --message-format=json >"$json" 2>"$err"; rc=$?; [ "$rc" -eq 0 ] && exit 0; grep -Eqi '(lock file .* needs to be updated|Cargo.lock needs to be updated)' "$err" && exit 61; grep -Eqi '(failed to parse manifest|manifest is virtual|invalid manifest)' "$err" && exit 62; grep -Eqi '(package ID specification .* did not match|package .* not found|no matching package named)' "$err" && exit 63; grep -Eqi '(requires rustc|rustc .* is not supported|unsupported rust version)' "$err" && exit 64; python - "$json" "$err" <<'PY'
import json, sys
codes=[]
messages=[]
with open(sys.argv[1], encoding='utf-8', errors='replace') as fh:
    for line in fh:
        try: obj=json.loads(line)
        except Exception: continue
        if obj.get('reason')!='compiler-message': continue
        msg=obj.get('message') or {}
        if msg.get('level')!='error': continue
        code=(msg.get('code') or {}).get('code')
        if code: codes.append(code)
        messages.append(msg.get('message',''))
text='\n'.join(messages)
if any(c in {'E0308'} for c in codes): raise SystemExit(71)
if any(c in {'E0499','E0500','E0501','E0502','E0503','E0505','E0506','E0382'} for c in codes): raise SystemExit(72)
if any(c in {'E0277','E0369'} for c in codes): raise SystemExit(73)
if any(c in {'E0599','E0425','E0432','E0433'} for c in codes): raise SystemExit(74)
if codes: raise SystemExit(75)
with open(sys.argv[2], encoding='utf-8', errors='replace') as fh: stderr=fh.read()
if 'test result: FAILED' in stderr or 'test failed' in stderr: raise SystemExit(76)
raise SystemExit(77)
PY
